  Copiado: { es: "Copiado", it: "Copiato", en: "Copied"},
  // ─── Configurações: Billing ───
  "Planos, faturas e cobrança.": { es: "Planes, facturas y cobros.", it: "Piani, fatture e fatturazione.", en: "Plans, invoices and billing."},
