  // ─── Índice de Atrito: os rótulos nascem em lib/metrics/atrito.ts ───
  //
  // Aquele arquivo é lógica pura e não conhece idioma; quem traduz é o ponto
  // de renderização (`AtritoPanel`). Eles chegavam à tela em português com a
  // interface em espanhol — achado pela spec e2e, não pelo guarda estático:
  // `{par.titulo}` é uma expressão, e o guarda só enxerga literal.
  "Atrito máximo: a pessoa pediu para sair.": { es: "Fricción máxima: la persona pidió darse de baja.", it: "Attrito massimo: la persona ha chiesto di uscire.", en: "Maximum friction: the person asked to leave."},
  "Confiança perdida na automação.": { es: "Confianza perdida en la automatización.", it: "Fiducia persa nell'automazione.", en: "Trust lost in the automation."},
  "Contenção": { es: "Contención", it: "Contenimento", en: "Containment"},
  "Conversão": { es: "Conversión", it: "Conversione", en: "Conversion"},
  "Custo humano": { es: "Costo humano", it: "Costo umano", en: "Human cost"},
  "Demandas abertas sem próximo passo": { es: "Demandas abiertas sin próximo paso", it: "Richieste aperte senza passo successivo", en: "Open requests with no next step"},
  "Demandas encerradas": { es: "Demandas cerradas", it: "Richieste chiuse", en: "Closed requests"},
  "Demandas que precisaram subir de nível": { es: "Demandas que necesitaron escalar", it: "Richieste che hanno dovuto essere escalate", en: "Requests that had to be escalated"},
  "Descadastros no período": { es: "Bajas en el período", it: "Disiscrizioni nel periodo", en: "Opt-outs in the period"},
  "Espera na fila humana (mediana)": { es: "Espera en la cola humana (mediana)", it: "Attesa in coda umana (mediana)", en: "Wait in the human queue (median)"},
  "Espera na fila humana (p90)": { es: "Espera en la cola humana (p90)", it: "Attesa in coda umana (p90)", en: "Wait in the human queue (p90)"},
  "Insistência do agente (média de retornos)": { es: "Insistencia del agente (promedio de retornos)", it: "Insistenza dell'agente (media dei ritorni)", en: "Agent persistence (average retries)"},
  "Insistência no pior caso": { es: "Insistencia en el peor caso", it: "Insistenza nel caso peggiore", en: "Persistence in the worst case"},
  "Intervenções humanas por demanda": { es: "Intervenciones humanas por demanda", it: "Interventi umani per richiesta", en: "Human interventions per request"},
  "Mensagens enviadas pelo agente": { es: "Mensajes enviados por el agente", it: "Messaggi inviati dall'agente", en: "Messages sent by the agent"},
  "Negócios ganhos": { es: "Negocios ganados", it: "Affari vinti", en: "Deals won"},
  "O cliente que mais recebeu retornos. A média esconde o exagero pontual.": { es: "El cliente que más retornos recibió. El promedio esconde el exceso puntual.", it: "Il cliente che ha ricevuto più ritorni. La media nasconde l'eccesso puntuale.", en: "The customer who received the most retries. The average hides the occasional excess."},
  "O time respondeu pelo celular, contornando a ferramenta.": { es: "El equipo respondió por el celular, esquivando la herramienta.", it: "Il team ha risposto dal cellulare, aggirando lo strumento.", en: "The team replied by phone, bypassing the tool."},
  "Passagens para humano": { es: "Pases a humano", it: "Passaggi all'umano", en: "Handoffs to human"},
  "Perguntas que a pessoa teve de repetir": { es: "Preguntas que la persona tuvo que repetir", it: "Domande che la persona ha dovuto ripetere", en: "Questions the person had to repeat"},
  "Quanto o sistema precisou ser contido de si mesmo antes de falar.": { es: "Cuánto el sistema necesitó ser contenido de sí mismo antes de hablar.", it: "Quanto il sistema ha dovuto essere trattenuto da sé stesso prima di parlare.", en: "How much the system had to be held back from itself before speaking."},
  "Respostas dadas pelo agente": { es: "Respuestas dadas por el agente", it: "Risposte date dall'agente", en: "Answers given by the agent"},
  "Respostas humanas fora do sistema": { es: "Respuestas humanas fuera del sistema", it: "Risposte umane fuori dal sistema", en: "Human replies outside the system"},
  "Turnos até o desfecho (mediana)": { es: "Turnos hasta el desenlace (mediana)", it: "Turni fino all'esito (mediana)", en: "Turns until the outcome (median)"},
  "Vetos por execução": { es: "Vetos por ejecución", it: "Veti per esecuzione", en: "Vetoes per execution"},
