  "arquivados": { es: "archivados", it: "archiviati", en: "archived"},

  // ═══ A Agenda, do PR #379 ═══
  //
  // Contribuição de @JowaniOrantes: as 71 entradas do módulo de Agenda —
  // grade, marcação, histórico, filtro de pessoas e o cartão da conexão com o
  // Google. Vocabulário herdado dos passes anteriores de propósito:
  // agendamento→cita, atendente→agente, marcar→agendar.
  "MMMM 'de' yyyy": { es: "MMMM 'de' yyyy", it: "MMMM yyyy", en: "MMMM yyyy"},
  "d 'de' MMM": { es: "d 'de' MMM", it: "d MMM", en: "MMM d"},
  "d 'de' MMMM": { es: "d 'de' MMMM", it: "d MMMM", en: "MMMM d"},
  "EEEE, d 'de' MMMM": { es: "EEEE, d 'de' MMMM", it: "EEEE, d MMMM", en: "EEEE, MMMM d"},
  "EEEE, d 'de' MMM": { es: "EEEE, d 'de' MMM", it: "EEEE, d MMM", en: "EEEE, MMM d"},
  "Cancelando…": { es: "Cancelando…", it: "Annullamento…", en: "Canceling…"},
  "Agenda conectada:": { es: "Agenda conectada:", it: "Agenda collegata:", en: "Calendar connected:"},
  "Conectar Google": { es: "Conectar Google", it: "Connetti Google", en: "Connect Google"},
  "atendido por": { es: "atendido por", it: "gestito da", en: "handled by"},

  // ─── Agenda (módulo inteiro: grade, marcação, histórico, tipos, Google) ───
  //
  // A Agenda nasceu depois do inventário de telas que guiou a tradução do resto
  // do produto, então nunca teve uma linha aqui: ~3.500 linhas de tela em
  // português, com o item já visível na barra lateral.
  //
  // Os CATÁLOGOS fechados que ela lê (`ROTULO_DA_SITUACAO` em lib/agenda/tipos.ts,
  // `DESFECHOS` do retorno do OAuth, as categorias de tipo de agendamento) são
  // traduzidos no ponto de render — os módulos não mudam, mesma fronteira dos
  // outros vocabulários deste arquivo.
  //
  // VOZ: tuteo, o padrão deste arquivo — as entradas do composer que estavam em
  // voseo já foram corrigidas antes deste bloco.
  //
  // VOCABULÁRIO: "agendamento" → "cita", que é o que este dicionário já usava
  // (11 ocorrências contra 1). A exceção é o estado vazio da Agenda, que diz
  // "Los agendamientos" — entrada que NÃO é deste bloco e por isso fica como
  // está; trocá-la é decisão de quem a escreveu, e vai anotada no PR.
  "Novo agendamento": { es: "Nueva cita", it: "Nuovo appuntamento", en: "New appointment"},
  "Remarcar agendamento": { es: "Reagendar cita", it: "Riprogramma appuntamento", en: "Reschedule appointment"},
  "Cancelar agendamento": { es: "Cancelar cita", it: "Annulla appuntamento", en: "Cancel appointment"},
  "Este agendamento não está mais na lista.": { es: "Esta cita ya no está en la lista.", it: "Questo appuntamento non è più nell'elenco.", en: "This appointment is no longer on the list."},
  "Agendamento": { es: "Cita", it: "Appuntamento", en: "Appointment"},
  "d 'de' MMMM 'às' HH:mm": { es: "d 'de' MMMM 'a las' HH:mm", it: "d MMMM 'alle' HH:mm", en: "MMMM d 'at' HH:mm"},
  "EEEE, d 'de' MMMM 'às' HH:mm": { es: "EEEE, d 'de' MMMM 'a las' HH:mm", it: "EEEE, d MMMM 'alle' HH:mm", en: "EEEE, MMMM d 'at' HH:mm"},
