  Impressões: { es: "Impresiones", it: "Impressioni", en: "Impressions"},
  Alcance: { es: "Alcance", it: "Copertura", en: "Reach"},
  CPM: { es: "CPM", it: "CPM", en: "CPM"},
  CTR: { es: "CTR", it: "CTR", en: "CTR"},
