  "Conversas iniciadas": { es: "Conversaciones iniciadas", it: "Conversazioni avviate", en: "Conversations Started"},
  "Primeiras respostas": { es: "Primeras respuestas", it: "Prime risposte", en: "First Replies"},
  Cadastros: { es: "Registros", it: "Registrazioni", en: "Sign-ups"},
  Compras: { es: "Compras", it: "Acquisti", en: "Purchases"},
