  "Ver conversas": { es: "Ver conversaciones", it: "Vedi conversazioni", en: "View conversations"},
  "A equipe": { es: "El equipo", it: "Il team", en: "The team"},
  "Os agentes": { es: "Los agentes", it: "Gli agenti", en: "The agents"},
  "Quem fez": { es: "Quién lo hizo", it: "Chi ha fatto", en: "Who did it"},
