  "Dados da organização": { es: "Datos de la organización", it: "Dati dell'organizzazione", en: "Organization details"},
  "Criar organização": { es: "Crear organización", it: "Crea organizzazione", en: "Create organization"},

  // Meet: estados, falhas e ações da agenda e mensagem transacional.
  "Google Meet": { es: "Google Meet", it: "Google Meet", en: "Google Meet"},
  "Abrir reunião": { es: "Abrir reunión", it: "Apri riunione", en: "Open meeting"},
  "Conversa que receberá o link": { es: "Conversación que recibirá el enlace", it: "Conversazione che riceverà il link", en: "Conversation that will receive the link"},
  "Nenhum atendimento aberto para este contato": { es: "No hay ninguna atención abierta para este contacto", it: "Nessuna conversazione aperta per questo contatto", en: "No open conversation for this contact"},
  "Link ainda não solicitado": { es: "Enlace aún no solicitado", it: "Link non ancora richiesto", en: "Link not requested yet"},
  "Criando link do Google Meet": { es: "Creando enlace de Google Meet", it: "Creazione del link Google Meet", en: "Creating Google Meet link"},
  "Link do Google Meet pronto": { es: "Enlace de Google Meet listo", it: "Link Google Meet pronto", en: "Google Meet link ready"},
  "Não foi possível confirmar o link": { es: "No se pudo confirmar el enlace", it: "Impossibile confermare il link", en: "Couldn't confirm the link"},
  "Solicitação de link cancelada": { es: "Solicitud de enlace cancelada", it: "Richiesta di link annullata", en: "Link request canceled"},
  "O envio do link ainda não foi autorizado.": { es: "El envío del enlace aún no ha sido autorizado.", it: "L'invio del link non è ancora stato autorizzato.", en: "Link sending hasn't been authorized yet."},
  "Envio autorizado: aguardando o link ficar pronto.": { es: "Envío autorizado: esperando a que el enlace esté listo.", it: "Invio autorizzato: in attesa che il link sia pronto.", en: "Sending authorized: waiting for the link to be ready."},
  "Link aguardando envio nesta conversa.": { es: "Enlace pendiente de envío en esta conversación.", it: "Link in attesa di invio in questa conversazione.", en: "Link waiting to be sent in this conversation."},
  "Link enviado na conversa autorizada.": { es: "Enlace enviado en la conversación autorizada.", it: "Link inviato nella conversazione autorizzata.", en: "Link sent in the authorized conversation."},
  "Entrega impedida. Confira o atendimento e o canal antes de autorizar novamente.": { es: "Entrega bloqueada. Revisa la atención y el canal antes de autorizar de nuevo.", it: "Consegna impedita. Verifica la conversazione e il canale prima di autorizzare di nuovo.", en: "Delivery blocked. Check the conversation and the channel before authorizing again."},
  "O atendimento mudou. Autorize uma nova entrega na conversa desejada.": { es: "La atención cambió. Autoriza una nueva entrega en la conversación deseada.", it: "La conversazione è cambiata. Autorizza una nuova consegna nella conversazione desiderata.", en: "The conversation changed. Authorize a new delivery in the desired conversation."},
  "O envio falhou. Confira o canal e tente novamente.": { es: "El envío falló. Revisa el canal e inténtalo de nuevo.", it: "L'invio non è riuscito. Verifica il canale e riprova.", en: "Sending failed. Check the channel and try again."},
  "Não foi possível copiar. Use o link de abrir reunião para acessar a sala.": { es: "No se pudo copiar. Usa el enlace para abrir la reunión y acceder a la sala.", it: "Impossibile copiare. Usa il link di apertura riunione per accedere alla sala.", en: "Couldn't copy. Use the open meeting link to access the room."},
  "Tentar criar link novamente": { es: "Intentar crear el enlace de nuevo", it: "Riprova a creare il link", en: "Try creating the link again"},
